/* Yue Lao oracle data (English) · sources noted in docs/qian-data-sources/yuelao.md */
window.QIAN_DATA = {
  id: "yuelao",
  total: 100,
  name: "Yue Lao Oracle Sticks",
  nameZh: "月老灵签",
  grades: ["上上大吉", "上上", "上吉", "上", "中上", "上平", "中平", "中", "下"],
  gradeLabels: { "上上大吉": "Most Auspicious", "上上": "Supreme", "上吉": "Excellent", "上": "Favorable", "中上": "Above Average", "上平": "Fairly Steady", "中平": "Steady", "中": "Neutral", "下": "Lower" },
  aspects: ["Love", "Marriage", "Reconciliation"],
  signs: [
    { no: 1, grade: "上上大吉", titleZh: "良缘天成", title: "A Match Made in Heaven", poemZh: "关关雎鸠\n在河之洲\n窈窕淑女\n君子好逑", poem: "Guan-guan cry the ospreys\non the islet in the river\nthe fair and graceful lady\na fine match for the lord", meaning: "A supreme stick that opens the set: love's season has come, and a worthy match awaits. For singles, the one you admire is likely your true match—speak up with courage. For couples, marriage beckons; for the married, lifelong harmony. Old Man Moon has tied the thread; all that is wanting is your boldness. Act before the moment passes.", aspects: ["Match in sight", "Lifelong harmony", "Boldness wins"] },
    { no: 2, grade: "中", titleZh: "孤鹜待时", title: "A Time of Solitude", poemZh: "落霞与孤鹜齐飞\n秋水共长天一色", poem: "The sunset glow flies with the lone wild duck\nautumn waters merge with the long sky in one hue", meaning: "Sunset and a lone duck: an image of solitude, not yet a season of union. Do not chase romance too hard just now; disappointment only deepens the chill. Keep faith, do good quietly, and let time turn. When fortune warms again, reunion and fulfillment will come of their own accord.", aspects: ["Not yet", "Stay calm", "Await the turn"] },
    { no: 3, grade: "上上大吉", titleZh: "祖荫绵长", title: "Ancestral Blessings", poemZh: "宗庙享之\n子孙保之", poem: "The ancestral temple enjoys its offerings\nand the descendants preserve them", meaning: "Blessings flow down from the ancestors: a deep-rooted, happy marriage is promised. Family life will be harmonious, with children and grandchildren around you. Singles need not fret—the match is heaven-arranged. Repay this inherited fortune with good deeds, so the blessing carries on to the next generation.", aspects: ["Blessed match", "Harmonious home", "Fulfilled"] },
    { no: 4, grade: "中", titleZh: "知过能改", title: "Correct Your Faults", poemZh: "斯人也，而有斯疾也\n斯人也，而有斯疾也", poem: "Such a man, and yet such an ailment\nsuch a man, and yet such an ailment", meaning: "Everyone carries flaws, even sages. Quarrels and suspicion in love usually grow from each other's faults; correct your own rather than criticize theirs. Where both are willing to mend their ways and speak honestly, the bond can begin anew. Picking at blemishes, however, ends in nothing good.", aspects: ["Guard against quarrels", "Mistakes mended", "Mendable"] },
    { no: 5, grade: "上", titleZh: "把握良缘", title: "Seize the Moment", poemZh: "逾东家墙而搂其处子，则得妻\n不搂，则不得妻", poem: "Climb the east wall and embrace the maiden, and you win a wife\nwithout embracing, you win none", meaning: "This stick is blunt: advance and you wed, retreat and you lose. Whether a chance meeting or someone close by your side, if you believe this person is marriageable, act—confess, court, embrace. Hesitation squanders a heaven-sent chance; for the married hoping for a child, extra joy. Do not stand still.", aspects: ["Act and win", "Press forward", "Decide now"] },
    { no: 6, grade: "上吉", titleZh: "好事将近", title: "Good News Nears", poemZh: "风弄竹声，只道金佩响\n月移花影，疑是玉人来", poem: "Wind stirs the bamboo—one takes it for jade pendants chiming\nthe moon shifts flower shadows—one fancies the beloved coming", meaning: "Wind in the bamboo, flower shadows in moonlight—someone dear seems very near. Good news approaches: singles will find romance close at hand, and couples may speak of marriage. Yet those already wed must hold to fidelity and resist passing temptations; only then does the blessing last.", aspects: ["Good news near", "Happy tidings", "An opening comes"] },
    { no: 7, grade: "上", titleZh: "修德待缘", title: "Cultivate Yourself First", poemZh: "斯是陋室\n唯吾德馨", poem: "This may be a humble room\nbut my virtue makes it fragrant", meaning: "A humble room, yet virtue makes it fragrant. Your season has not come; now is the time for self-cultivation. Polish your learning and character, and a kindred spirit will find you out. Those with partners should drop the lonely-hero pose—communicate, be tender, and end cold wars before they harden.", aspects: ["Grow first", "Talk more", "A slow mend"] },
    { no: 8, grade: "中上", titleZh: "两情相悦", title: "Mutual Affection", poemZh: "期我乎桑中\n要我乎上宫\n送我乎淇之上也", poem: "She awaits me in the mulberry grove\ninvites me to the upper tower\nsees me off by the Qi river", meaning: "Marriage is a lifelong matter and must rest on mutual willingness. Court along honest roads and win the heart sincerely; unions taken by force or trickery are marriages in name only. If the affection is real, honest courtship will succeed; where hearts do not meet, parting sooner is the kinder path.", aspects: ["Sincerity wins", "No forcing", "Let it be"] },
    { no: 9, grade: "下", titleZh: "慎交慎择", title: "Choose with Care", poemZh: "则父母国人皆贱之", poem: "Then parents and neighbors alike will despise you", meaning: "A lower stick, warning against rash, unheeding choices. Bad company and stubbornness earn the contempt of parents and neighbors alike. Weigh the advice of elders; if the one before you is flawed in character, end it cleanly however deep the feeling. One misstep can grieve you for a lifetime.", aspects: ["Hold back", "Guard harmony", "Do not rush"] },
    { no: 10, grade: "上", titleZh: "天伦之乐", title: "Family Bliss", poemZh: "有道是养儿防老\n积谷防饥", poem: "As the saying goes, raise children for your old age\nstore grain against famine", meaning: "Raise children for old age; store grain against famine. Marriage and family ask early tending, and the harvest is the joy of ordinary days. The unmarried should not idle away the years; the married should sow affection daily—love stored up, like grain, will feed you both in later life.", aspects: ["Settle soon", "Deep conjugal love", "Steady gain"] },
    { no: 11, grade: "中平", titleZh: "去旧迎新", title: "Release the Past", poemZh: "自剪芭蕉写佛经\n金莲无复印中庭\n清风明月长相忆\n玉管朱弦可要听\n多病不胜衣更薄\n宿妆犹在酒初醒\n经年违别成何事\n卧看牵牛织女星", poem: "I cut banana leaves myself to copy the sutras\nthe golden lotus prints the courtyard no more\nin clear breeze and bright moon I remember you long\nwill you not hear flute and crimson strings\ntoo frail with illness, my clothes hang thin\nlast night's makeup lingers as the wine wears off\nafter years apart, what has come of it\nI lie watching the Herdboy and Weaver stars", meaning: "A page of old longing—cut banana leaves, copied sutras, remembered music. Cherishing the past repairs nothing. Put down what has sunk away, tend body and spirit, and let new fortune find you; married couples should release old grievances and treasure the person present. The past is gone; the future can still be welcomed.", aspects: ["Release the old", "Bury the past", "Begin afresh"] },
    { no: 12, grade: "中", titleZh: "忧喜参半", title: "Joy Mixed with Care", poemZh: "一则以喜\n一则以惧", poem: "At once a cause for joy\nat once a cause for fear", meaning: "Nothing in this world is perfect; love brings joy and worry in one breath. Face the mixture honestly, weigh what you have, and do not demand fullness nor despair at small stumbles. In marriage, difficulty comes first and sweetness after—patience carried through turns the tide.", aspects: ["Mixed fortune", "Worse, then better", "Go with fate"] },
    { no: 13, grade: "上", titleZh: "绝处逢生", title: "A Turn of Fortune", poemZh: "山穷水尽疑无路\n柳暗花明又一村", poem: "Hills end, waters fade—no road in sight\nthen willow shade and blossoms: another village appears", meaning: "Where hills and waters seem to end, a village appears beyond the willows. A romance at its lowest ebb may yet revive; the separated may reconcile, the remarried find happiness. But do not wait on go-betweens—go and win the person yourself. A firm heart finds the road.", aspects: ["Relief nears", "Hard, then easy", "Revival possible"] },
    { no: 14, grade: "上上", titleZh: "爱屋及乌", title: "Love Wholly", poemZh: "谁谓荼苦\n其甘如荠\n宴尔新婚\n如兄如弟", poem: "Who says the sowthistle is bitter\nto me it is sweet as shepherd's purse\nfresh and glad in new marriage\nwarm as brothers in accord", meaning: "To true love, bitterness tastes sweet as shepherd's purse. Choose a mate not by rank or purse but from the heart; embrace all of who they are, and hardship turns honey-sweet. A union so grounded stays honeymoon-fresh for life. The bond before you is steady—tend it without worry.", aspects: ["Sweet despite hardship", "Stable and warm", "True love lasts"] },
    { no: 15, grade: "中", titleZh: "守礼防嫌", title: "Keep Propriety", poemZh: "君子审礼\n不呆诬以奸诈", poem: "The gentleman observes the rites\nnone can accuse him of deceit", meaning: "Passion must stop at propriety; light conduct hands the world a stone to throw. Keep dignified and above reproach, and slander finds no foothold; deceit, however, repays itself in time. Your fortune is ordinary just now—build character first; an upright course carries love farthest.", aspects: ["Keep propriety", "Avoid entanglements", "Upright is safe"] },
    { no: 16, grade: "上上", titleZh: "情投意合", title: "Hearts in Accord", poemZh: "意中人\n人中意\n则那些无情花鸟也情凝\n一般的解结枝头学并栖", poem: "The one in my heart\nthe one whose heart holds me\neven unfeeling flowers and birds are stirred to feeling\nalike on the branches they nestle two by two", meaning: "You have a liking, and you are liked in turn—so deep a current that even flowers and birds catch the feeling. Show your whole heart plainly; affection draws fate along behind it. Couples see misunderstandings melt—spring brings helpful go-betweens, and autumn's obstacles still end well. Two hearts as one soften any ill luck.", aspects: ["Mutual delight", "Obstacles fade", "Full reconciliation"] },
    { no: 17, grade: "中", titleZh: "重德轻财", title: "Virtue over Wealth", poemZh: "德者本也\n财者末也", poem: "Virtue is the root\nwealth is but the branch", meaning: "Virtue is the root, wealth only the branch; invert the two and trouble follows. A marriage grasped at for riches, with character slighted, may be grand yet will seldom stay peaceful. If a candidate stands before you, weigh conduct first and fortune after. For the married, mutual support through thick and thin, grounded in honor, is the road that lasts. Do not climb for vanity's sake.", aspects: ["Virtue first", "Support each other", "Practical success"] },
    { no: 18, grade: "上", titleZh: "尽情告白", title: "Speak Your Heart", poemZh: "非独内德茂也\n盖亦以外感之助焉", poem: "Inner virtue alone is not enough\noutward expression must lend its aid", meaning: "Fine inner worth still needs outward expression to be seen and trusted. If someone holds your heart, do not keep it hidden: show your feeling and your substance sincerely, and let trust grow from it. Too much shyness leaves the other never knowing, and the chance brushes past. For the married, open exchange of hearts dissolves worry and keeps the blessing long.", aspects: ["Confess soon", "Candor brings luck", "Actively win back"] },
    { no: 19, grade: "中", titleZh: "静待缘熟", title: "Wait for Ripeness", poemZh: "或十年\n或七八年\n或五六年\n或三四年", poem: "Perhaps ten years\nperhaps seven or eight\nperhaps five or six\nperhaps three or four", meaning: "The appointed time has not come: this bond needs years to ripen—three or four at the least, ten at the most. For those parted by distance, work, or study, meeting and parting keep their own schedule, and hurrying is useless. The longing is bitter, yet it ripens into shared sweetness. Rather than press and force, wait patiently and store up merit; when the season matures, all flows into place.", aspects: ["Not yet ripe", "Bitter then sweet", "Long wait wins"] },
    { no: 20, grade: "上", titleZh: "凡事可图", title: "The Answer Is Yes", poemZh: "何如\n子曰\n可也", poem: "What of it?\nThe Master said\nIt may be done", meaning: "The sage's single word settles it: what you ask about may be pursued, so do not hesitate. Wondering whether the one before you can be trusted for life? Consult your elders and teachers; their approval adds assurance. Once the answer is yes, resolve to advance at once—the moment is fleeting. Husband and wife acting with one heart will likewise find their matters carried through.", aspects: ["Go ahead", "Elders approve", "Seize today"] },
    { no: 21, grade: "上上", titleZh: "乐天知命", title: "Content and Blessed", poemZh: "十亩之间兮\n桑者闲闲兮", poem: "Among ten acres of fields\nthe mulberry pickers take their ease", meaning: "A homestead of ten acres, mulberry pickers at their ease: a picture of sufficiency and calm. The bond heaven has granted you is already enough; small frictions aside, keeping to your own lot brings it to fullness. Do not let passing beauty or gain tempt you into restlessness—craving without end invites ruin. Cherish the bond before you, and contentment carries you to a union of a hundred years.", aspects: ["Contentment is peace", "A hundred years", "Count your blessings"] },
    { no: 22, grade: "上上大吉", titleZh: "四喜临门", title: "Fourfold Joy", poemZh: "久旱逢甘雨\n他乡遇故知\n洞房花烛夜\n金榜挂名时", poem: "Sweet rain after long drought\nan old friend met in a far land\nthe wedding night by flowered candles\none's name posted on the golden roll", meaning: "All four great joys of life arrive at once—a rare and mighty sign among the hundred. The marriage flows to its natural close: lovers become husband and wife, live afterward like a pair of immortals, and happy events keep arriving in train. With fortune so full, repay it—do good, give warmly to others, and let the accumulated kindness keep this blessing flowing without end.", aspects: ["Joy at hand", "An immortal pair", "All delights"] },
    { no: 23, grade: "中", titleZh: "作茧自缚", title: "The Silkworm's Cocoon", poemZh: "只一点故情留\n直似春蚕到老\n尚把丝抽", poem: "One thread of old affection remains\njust like the spring silkworm that to its very end\nstill spins out its silk", meaning: "The spring silkworm spinning to its last breath is a warning against devotion carried past all sense. Love that blinds and binds only wastes your own years; excess, like scarcity, accomplishes nothing. This bond may be remembered, but it cannot be rewoven—once the other's heart is fixed, pressing is useless. Keep to the middle way, gather worth about you, and open a new sky.", aspects: ["Blind love harms", "Pressing is vain", "Let go"] },
    { no: 24, grade: "中", titleZh: "怨结难解", title: "Grievance Runs Deep", poemZh: "他思已穷\n恨不穷\n是为娇鸾雏凤失雌雄", poem: "His thoughts are spent\nyet the hatred is not\nso the tender phoenix pair loses its mate", meaning: "Love exhausted turns to grievance: the phoenix has lost its mate—a red light is blinking over this bond. The other's resentment runs deep; treat it lightly and you may end with nothing. Those with children, be doubly careful—do not let flesh and blood be parted. Lower yourself, win them back, dissolve the knot with sincerity, and ask Old Man Moon's help through good deeds; a turn is still possible.", aspects: ["Grudges deepen", "Win back soon", "A turn possible"] },
    { no: 25, grade: "上", titleZh: "良缘可许", title: "A Worthy Match", poemZh: "可妻也", poem: "This one may be taken as a wife", meaning: "A single word—yes: the person before you is precisely the one you may marry. Small frictions and delays along the way are nothing; let matters take their course and the water will find its channel. Once the union is made, love's long river and growing old together can both be counted on. Gather merit, cherish this heaven-given bond, and never let trivialities stall your decision.", aspects: ["Commit for life", "Grow old together", "Let it unfold"] },
    { no: 26, grade: "上上", titleZh: "熊虺呈祥", title: "Omens of Children", poemZh: "维熊维罴\n男子之祥\n维虺维蛇\n女子之祥", poem: "A dream of bears\nthe omen of a son\na dream of vipers and snakes\nthe omen of a daughter", meaning: "Dreaming of bears foretells a son, of snakes a daughter: an auspicious sign of children born and the household flourishing. For the married, a new child is coming—the joy of a hundred heirs and a thousand grandsons. For those discussing marriage, it likewise promises a fitting home and family. With fortune so full, give to good works; the merit will shelter your descendants and keep the family line long.", aspects: ["A happy sign", "Children bring luck", "Household rising"] },
    { no: 27, grade: "上平", titleZh: "莫攀门第", title: "Mind Not the Pedigree", poemZh: "有宗室之美", poem: "There is the beauty of noble lineage", meaning: "Pedigree is nothing to lean on: in this age all stand equal, and love and affinity must weigh most in choosing a mate. Pride in status—climbing above your station or lording it over others—misleads you and everyone else. Seek in an ordinary household and you may find a solid, honest match. Fortune runs average now: drop the question of rank, gather goodwill, and contentment will bring the hundred-year union.", aspects: ["Rank matters not", "Be content", "Release, then gain"] },
    { no: 28, grade: "上", titleZh: "相敬如宾", title: "Mutual Respect", poemZh: "夫妇也\n昆弟也", poem: "Husband and wife\nare brothers of one hearth as well", meaning: "Once wed, husband and wife should be as brothers of the same hearth—treating each other with the courtesy due an honored guest, loving and trusting without reserve. For the unmarried, the bond will be steady and enduring, worthy of your whole trust. For the married, support each other as twin wings on one branch, tolerant of each other's everything. So tended, the union brings lifelong happiness—extend it with good deeds.", aspects: ["Deep devotion", "A hundred years", "Good as new"] },
    { no: 29, grade: "中平", titleZh: "姻缘天定", title: "Fate Decrees", poemZh: "有意栽花花不发\n无心插柳柳成荫", poem: "Plant flowers with great care—they never bloom\nthrust a willow twig in idle ground—it gives deep shade", meaning: "Marriage is arranged in secret by heaven: those who strive hardest come up empty-handed, while the unplanted willow casts the shade. The one you chase so painfully may not be your destiny; a chance, unintended meeting may yet become a hundred-year union. Rather than force the issue, yield to nature and loosen your grip. What is lost at sunrise may be regained by sunset—who can say?", aspects: ["Forcing fails", "Let fate bring", "Loss holds gain"] },
    { no: 30, grade: "中", titleZh: "镜花水月", title: "Flowers in a Mirror", poemZh: "话别无长夜\n相思又此春\n瑶姬不可见\n巫峡更何人\n运石疑填海\n乘槎欲问津", poem: "We spoke farewell through the endless night\nlonging returns with another spring\nthe Jade Maiden cannot be seen\nwho else dwells in the Wu Gorge?\nhauling stones, one dreams of filling the sea\nsailing a raft, one seeks a crossing", meaning: "Cloud and rain over Mount Wu stand for love across a distance: the one longed for is remote beyond reach, all this devotion is flowers in a mirror, moon in the water. Secret or triangular affections call for a hard look—better to honor the real life before you than dream of misty rendezvous. The bond is shallow; do not interrogate gods or futures. Hold fast to today; something will come.", aspects: ["Beyond reach", "Guard against affairs", "Chase no mirage"] },
    { no: 31, grade: "中平", titleZh: "空载明月", title: "Boat Laden with Moonlight", poemZh: "设虚\n夜静水寒\n鱼不饵\n笑满船空载明月", poem: "The trap is set in vain\nthe night still, the water cold\nthe fish will not take the bait\nlaughing—a whole boat loaded only with moonlight", meaning: "Angling in a cold pool, the fish refuse the bait; the boat comes home laden only with moon. The moment is wrong, and what you seek falls through. In love, do not thrash about; worse still, do not gamble on luck or steal forbidden sweetness—never let cold war and suspicion gnaw the root. Return to what is real, spread goodwill, and when the spring water warms, the catch will come.", aspects: ["Fruitless for now", "Avoid cold wars", "Not yet time"] },
    { no: 32, grade: "上", titleZh: "何幸得偶", title: "Fortunate to Wed", poemZh: "因荷而得藕\n有杏不须梅", poem: "Through the lotus one gains its root—so, by chance, a mate\nwith apricots at hand, no plum is needed—so, with luck, no go-between", meaning: "Lotus root and apricot hide the words for mate and no-go-between: a sign of a match arranged across three lifetimes. Singles need not search far and wide—the intended one may already stand near at hand, and a chance meeting is the true bond. Those discussing marriage will find matters flow into place without a matchmaker's help. Fortune runs high: merit prolongs it, and the hundred-year union can be trusted.", aspects: ["Chance brings love", "No matchmaker needed", "A bond restored"] },
    { no: 33, grade: "上上", titleZh: "可托终身", title: "Worthy of Trust", poemZh: "可以托六尺之孤\n可以寄百里之命", poem: "To such a one you may entrust an orphaned child\nto such a one you may commit the fate of a hundred li", meaning: "The one you have met could be entrusted with an orphan or a city—the soul of good faith. In marriage, this promises a partner to trust with your whole life. Singles may soon find a helpful hand joins them with a kindred spirit—give your whole heart. For the married, a spouse loyal and dependable, and the household rising. Old Man Moon grants a beautiful ending; prolong it with good works.", aspects: ["A kindred spirit", "Trust for life", "Trust restored"] },
    { no: 34, grade: "中平", titleZh: "守旧待时", title: "Hold and Wait", poemZh: "仍旧贯\n如之何\n何必改作", poem: "Keep to the old way\nwhat of it?\nwhy must it be remade?", meaning: "Though you walk a rough patch, keep the old course and hold steady; do not chase novelty. When love runs ill, first grow quiet and observe; think the plan through before you break. Rushing to quit, or taking a new lover in the dark, only multiplies the tangles. Keep to your post and the moment will come—those hoping to reconcile should hold still and wait for the turn.", aspects: ["Keep the old", "No rash moves", "Await the turn"] },
    { no: 35, grade: "下", titleZh: "当断则断", title: "Cut It Off", poemZh: "遇人之不淑矣", poem: "You have met with one who is not good", meaning: "A lower stick, plainly spoken: the one you have met is not good, and clinging any longer invites harm. Since they are of a harmful sort and you know they cannot be kept, cut your losses quickly and choose a better mate. Long pain is worse than short—every added day of doubting cuts deeper. Withdraw in time, gather good connections, and fortune will turn back. Do not gamble on luck.", aspects: ["A bad match", "Cut it soon", "Look elsewhere"] },
    { no: 36, grade: "上", titleZh: "以诚相待", title: "Sincerity Repaid", poemZh: "投我以木桃\n报之以琼瑶", poem: "You threw me a quince\nI return a disc of jade", meaning: "A quince given is answered with jade: treat others in good faith, and the reward is sure. In love, a true heart is repaid with more than its measure; rather than keep score, spend generously on the bond. Singles who meet others sincerely knit good ties; married couples who love and yield grow deeper affection by the year. Hold to this rule, and the union will be happy.", aspects: ["Sincerity repaid", "Love deepens daily", "Warmth returns"] },
    { no: 37, grade: "中", titleZh: "把握机会", title: "Seize the Chance", poemZh: "求则得之\n舍则失之", poem: "Seek it, and it is gained\ndrop it, and it is lost", meaning: "The chance stands open: seek and you gain; let go and you lose—and once past, it cannot be chased back. Red luck runs with you now, so whether confessing love, discussing marriage, or mending an old bond, act and take hold; shrink back, and the opening closes in a blink. Lovesickness over gain and loss is the great enemy here—once you see clearly, move. The hesitaters mostly repent empty-handed.", aspects: ["Seek and gain", "Time it well", "Act, don't wait"] },
    { no: 38, grade: "上吉", titleZh: "敬妻如亲", title: "Honor Your Spouse", poemZh: "妻焉者\n亲之主也", poem: "The wife\nis the chief of one's own kin", meaning: "The wife is the dearest person beside parents and brothers, and deserves the same honor shown one's own flesh. For the unmarried, this promises a harmonious household and a capable, kindly helpmeet to come. For the married, examine how you treat your spouse: honor and tenderness, and no wounding neglect. Husband and wife are one body—where mutual respect holds, the family fortunes rise and blessing runs long.", aspects: ["A worthy spouse", "Household harmony", "Respect brings peace"] },
    { no: 39, grade: "上", titleZh: "孝悌为本", title: "Filial Piety First", poemZh: "不得乎亲\n不可以为人\n不顺乎亲\n不可以为子", poem: "Who wins not the hearts of his parents\ncannot stand as a person\nwho serves them not in duty\ncannot stand as a son", meaning: "Filial devotion is the root of character: win the hearts of your kin before you can win the world's. Those heading toward marriage should first settle the elders at home—their blessing smooths the whole road. For the married, tend both sets of parents and keep peace with siblings: a quiet household makes the marriage firm. All human affairs begin in filial duty, and from it the blessing grows.", aspects: ["Elders' blessing first", "Home at peace", "Duty before all"] },
    { no: 40, grade: "中", titleZh: "踏破铁鞋", title: "Iron Shoes Worn Through", poemZh: "踏破铁鞋无觅处\n得来全不费功夫", poem: "Iron shoes worn through in the searching—nowhere to be found\nit arrives without costing the least effort", meaning: "Where the iron shoes wore through, not a trace; once you let go, it comes without the least effort. Love pursued with straining is mostly labor lost: better to lay the obsession down and be kind to yourself—an unexpected meeting may wait just around the corner. Effort carried to the last is repaid in the end, only never in the shape you expected. Wait quietly for the chance.", aspects: ["Searching fails", "It comes unbidden", "A chance meeting"] },
    { no: 41, grade: "上平", titleZh: "识人须慎", title: "See Through the Mask", poemZh: "良人者\n所仰望而终身也\n今若此", poem: "A good spouse\nis the one we look up to for life\nbut now—like this!", meaning: "The one you looked up to for life has shown their lining, and must now be weighed anew. If you discover falseness and borrowed plumes, drift away by degrees and cut decisively, before regret writes its record. Fortune runs ordinary: in choosing a mate, look hard at character and foundations. For the married, watch more, talk more, and never let the surface dazzle you.", aspects: ["Test what's true", "Beware the surface", "See, then choose"] },
    { no: 42, grade: "中", titleZh: "否极泰来", title: "Clouds Will Lift", poemZh: "重重叠叠上瑶台\n几度呼童扫不开\n刚被太阳收拾去\n却教明月送将来", poem: "Layer on layer they climb the jasper terrace\ntime after time the boy is called to sweep—swept clean away\njust as the sun has gathered them up\nthe bright moon sends them back again", meaning: "Shadows on the terrace that no sweeping clears: a sudden loss or blockage stands before you, but within days an unexpected gain repays it. The gloom over your love will be scattered by sun and moonlight alike; where the way runs blocked, someone sends the light in. For now, wait patiently and make no hasty decisions—give it time, and the willow shade and blossoms appear.", aspects: ["The gloom lifts", "Blocked, then clear", "Waiting succeeds"] },
    { no: 43, grade: "上吉", titleZh: "两情相许", title: "Hearts Respond", poemZh: "君子有援琴之挑\n淑女无投梭之拒", poem: "The gentleman offers his suit with the zither\nthe lady makes no shuttle-hurling refusal", meaning: "The gentleman may press his suit with music and grace, and the lady has no cause to refuse at a thousand paces: the hour of mutual consent has come. Single men with someone in their heart may boldly show it and meet a gracious answer; a woman drawing this stick may trust her marriage to flow naturally. Only let courtship stay sincere and courteous—pleasing in feeling and right, never flippant.", aspects: ["Show your suit", "A willing answer", "Consent is near"] },
    { no: 44, grade: "上", titleZh: "新不如旧", title: "Old Beats New", poemZh: "遐迩一体\n率宾旧王", poem: "Far and near, one body\nall follow the ancient king", meaning: "The new does not equal the old: remembering old bonds and keeping what you have is the true road. The old love before you has its own thickness; tossing it away for a new flame costs more than it pays. A bond broken and distant is worth treasuring—reconciliation is no poor ending. Hold to old friends' affection and the portion already yours; manage it steadily, and fortune walks in.", aspects: ["Treasure the old", "Keep what's yours", "Old bonds renew"] },
    { no: 45, grade: "上", titleZh: "慎择佳偶", title: "Choose with Patience", poemZh: "后生可畏\n焉知来者之不如今也", poem: "The rising young are to be held in awe\nhow do you know those who come will not match the present?", meaning: "Those who come after need not be less: pleasing as the present candidate is, the next may prove better still. Let the choosing flow slow and long—observe on many sides, weigh character, learning, and health together, and decide with care. Those already seeing someone need not fix the outcome at once; a few more months show the true grain. Better to wait for the right than take the wrong.", aspects: ["Better may come", "Choose slowly", "Watch, then decide"] },
    { no: 46, grade: "中上", titleZh: "问心无愧", title: "A Clear Conscience", poemZh: "不愧于天\n不怍于人", poem: "No shame before Heaven\nno blush before men", meaning: "Walk square, and look up or down without shame: at a midnight knock the heart does not startle. In love, if your conscience is clear you need not dread the buzzing of tongues; stand straight, and the bond holds firm of itself. For the married, keep faith and deal candidly, and the gossip from outside will collapse of its own weight. An upright heart is the best amulet there is.", aspects: ["Conscience clear", "Rumor self-destructs", "Upright and steady"] },
    { no: 47, grade: "中", titleZh: "为人作嫁", title: "Sewing for Others", poemZh: "害女红者也", poem: "It is the bane of women's needlework", meaning: "The sewing woman stitches bridal gowns all year yet has no gown of her own to wear. In love, silent labor poured out for another's sake rarely buys cherishing—most often you are sewing the wedding dress for someone else. Respect and value yourself: give in measure, and let the other see plainly what you are worth. Do not consent to be the unnamed hand behind the curtain.", aspects: ["Giving goes unpaid", "Keep some reserve", "Value yourself"] },
    { no: 48, grade: "上吉", titleZh: "慧眼择郎", title: "A Discerning Eye", poemZh: "五百英雄都在此\n不知谁是状元郎", poem: "Five hundred heroes stand assembled here\nand no one knows which will wear the laurel crown", meaning: "A hall full of heroes, each with his luster, and no telling yet which one wears the crown. Singles face a wealth of choice—and plenty is why care is owed. Choose your ideal man by character first and learning second; never let purse or pedigree lead, or regret will arrive too late. Those with a partner should keep their eyes on the one before them—glancing both ways loses both.", aspects: ["Choose with care", "Character first", "Single-hearted"] },
    { no: 49, grade: "上平", titleZh: "审慎取舍", title: "Weigh with Time", poemZh: "故好而知其恶\n恶而知其美者", poem: "To love a person yet know their faults\nto dislike a person yet know their merits", meaning: "Long dwelling with the beloved reveals flaws; dwelling with the unloved reveals virtues—between love and dislike, only time can judge. The one who dazzles you is not wholly perfect; the one who leaves you flat is not without strengths. Judge calmly, choose carefully, and never let a season's feeling settle a lifetime. Give each other more days, and the answer will surface on its own.", aspects: ["Not by taste", "Time reveals", "Decide after watching"] },
    { no: 50, grade: "中", titleZh: "宜谈婚嫁", title: "Time to Marry", poemZh: "两世一身\n形单影只", poem: "Two generations, a single heir\none shadow, one solitary form", meaning: "To pass through life alone—a single shadow by a single form—is no long-term plan. That men should wed and women marry is a law older than memory; better to begin a real courtship aimed at marriage than to hold onto solitary ease until the years grow lonely. A home of one's own is itself a way of cherishing blessing and easing life's dryness. Do not cling to stubbornness.", aspects: ["Leave solitude", "Court to marry", "Take the hand"] },
    { no: 51, grade: "上", titleZh: "专一不移", title: "Stay Devoted", poemZh: "虽有善者\n亦无如之何矣", poem: "Though finer ones appear\nnothing can be done about it", meaning: "The allotment is fixed: even should a better figure appear, it comes to nothing. The bond before you is your appointed portion; a swiveling heart only squanders years. Fix on the one and give them your lifetime—that is where steadiness lies. Love's worth is wholeheartedness: the one who keeps glancing aside ends empty on both sides. Keep to the bond at hand and tend it with a quiet heart.", aspects: ["Fixed bond holds", "Devotion above all", "Steadfast wins"] },
    { no: 52, grade: "上上大吉", titleZh: "风云际会", title: "Winds and Clouds Meet", poemZh: "云从龙\n风从虎\n圣人作而万\n君万事皆可成也", poem: "Clouds follow the dragon\nwind follows the tiger\nthe sage arises—and the myriad lords\nall things may be brought to pass", meaning: "Clouds follow the dragon, wind follows the tiger: an extraordinary meeting of forces in which everything may be accomplished. Red luck rides high in your marriage—confessions and proposals go as you wish, and after the wedding the family fortunes rise in step. A chance like this comes once in a thousand years: ride the momentum and press forward boldly. Store up merit as well, so the good run stays.", aspects: ["The prime hour", "All things succeed", "Ride the momentum"] },
    { no: 53, grade: "上上", titleZh: "意外良缘", title: "Unexpected Blessing", poemZh: "其所厚者薄\n而其所薄者厚", poem: "What they treated thickly turns out thin\nand what they treated thinly turns out thick", meaning: "The world outruns expectation: what is treated thickly answers thin, what is treated thinly answers thick—and marriage is no exception. The one you bank on deeply may repay you thinly; the one you never minded may return you a fortune. An unexpectedly good match is coming to unite you. Bear kindness without keeping count; do good without reckoning reward—Heaven has a better arrangement waiting just behind.", aspects: ["A surprise awaits", "Rich repayment", "Unminding gains"] },
    { no: 54, grade: "中", titleZh: "婚事自主", title: "Decide for Yourself", poemZh: "成也萧何\n败也萧何", poem: "Success came through Xiao He\nand ruin came through Xiao He too", meaning: "The same hand that raises you can cast you down: the words of parents and matchmakers are not to be trusted whole, nor thrown away whole. Marriage is a great matter—state your case to your parents and seek their understanding; weigh the matchmaker's words with care. But the final decision must rest in your hands. Use your right to judge well, and no third person will lead you wrong.", aspects: ["Judge for yourself", "Weigh elders' words", "Your call decides"] },
    { no: 55, grade: "上", titleZh: "舍旧迎新", title: "Old Gone, New Comes", poemZh: "不思旧姻\n求尔新君", poem: "Do not pine for the old bond\nseek your new lord", meaning: "The old marriage is gone; there is no profit in pining, and a wide new country lies ahead. You who have walked out of the last love—lift your eyes to the road and go on, neither losing heart nor swelling with pride. New candidates, new bonds are on the way. Letting go is not betrayal: it opens a new life for you both. Do not sit imprisoned in memory.", aspects: ["Release the old", "The new ahead", "Forward is best"] },
    { no: 56, grade: "上上", titleZh: "百年好合", title: "Union of a Lifetime", poemZh: "永老无离别\n万古当团聚\n愿天下有情人\n都成眷属", poem: "May you grow old without parting\nthrough ten thousand ages remain together\nmay all lovers under heaven\nbe joined as man and wife", meaning: "This is Old Man Moon's own great vow: that all lovers under heaven become husbands and wives, growing old without parting. In your marriage it promises the red phoenix star—two hearts already in tune may look for a hundred years of union and harp-and-lute harmony. Cherish this heaven-sent fullness, keep one heart with your beloved, and treat the world with kindness—pass the completeness on to those around you.", aspects: ["Lovers united", "A hundred years", "Renewed fullness"] },
    { no: 57, grade: "上上", titleZh: "凤凰和鸣", title: "Phoenixes in Harmony", poemZh: "是谓凤凰于飞\n和鸣锵锵", poem: "This is the phoenix pair flying together\ntheir harmonious call ringing clear", meaning: "Phoenixes on the wing, their concerted call ringing out: the most beautiful of marriage omens. Singles will surely find a fine bond—two phoenixes soaring in one sky. Those discussing marriage meet a mate made in heaven, and after the wedding, harp and lute in accord to white hair. Small squalls cannot dent the joy of such a bond. Cherish the blessing, do good, and let it run long.", aspects: ["Made in heaven", "Lifelong harmony", "Sweet as first"] },
    { no: 58, grade: "中", titleZh: "不必高攀", title: "Climb Not Too High", poemZh: "帷旧婚媾\n其能降以相从乎", poem: "But for an old marriage alliance\nwould they ever stoop to follow you?", meaning: "To climb above your own measure, even if you succeed, seldom satisfies. Great houses do not guarantee good mates, and the phoenix on the branch cannot be judged by plumage. Better to lower your sights than live at another's nod—head of chickens rather than tail of oxen. Choose for fitness and ease of heart; feet on the ground win the real blessing. Let vanity mislead you no further.", aspects: ["Don't overreach", "Fit is best", "Lower, then gain"] },
    { no: 59, grade: "中", titleZh: "各有所好", title: "Each to His Taste", poemZh: "脍炙\n所同也\n羊枣\n所独也", poem: "Minced delicacies\nare what all share\nthe black jujube\nis his alone", meaning: "Minced delicacies are what everyone loves; the rare black jujube is one man's private taste. So it is in love: the very type you favor is scarce in this world, and getting less than others is simply natural. Rather than sigh over thin fortune, adjust your hopes and widen your standard. Know your own taste and keep faith with it—in time, the rare one comes round.", aspects: ["Hard to find", "Widen the standard", "Scarce bonds ripen"] },
    { no: 60, grade: "中", titleZh: "心安理得", title: "A Heart at Peace", poemZh: "心苟不愆\n何惜于人言", poem: "If the heart does no wrong\nwhy heed what people say?", meaning: "A straight heart owes no apology—why fear the crowd's chatter? If your love walks straight and loves truly, let others talk and suspect as they will; a conscience clear of guilt knows no fevered nights. For the married, candor lets rumor collapse of itself; for the unmarried, once the right bond is found, walk it with an easy gait. The heart at peace is the true home.", aspects: ["Heart at ease", "Clear conscience holds", "Meet it confident"] },
    { no: 61, grade: "上", titleZh: "观友知人", title: "Know One by Friends", poemZh: "不知其人\n视其友", poem: "If you would know a person\nlook at their friends", meaning: "To know the person, read the company they keep: the way of friendship is also the way of choosing a mate. To weigh the one you fancy, watch the friends they keep—straight or crooked—and character stands revealed. If the friends are upright and unbought, the person may be trusted for life; if the friends are loose and vain, think thrice. One more look before the wedding saves ten regrets after.", aspects: ["Read the friends", "Watch, then decide", "Mind the circle"] },
    { no: 62, grade: "上上大吉", titleZh: "嘉偶天成", title: "A Matched Pair", poemZh: "嘉耦曰配", poem: "A fine pair—that is what a true match is", meaning: "'A fine pair is called a match': the utmost sign of heaven-made mates fitted without seam. The two of you get along, and after a stretch of courtship the intent grows plain—if it may join, let it join—hesitate no more. This bond is fixed by destiny, and good it will end. Those discussing marriage may proceed freely; after the wedding the household blooms. Guard the blessing with good deeds.", aspects: ["A perfect match", "Destiny's bond", "A bond renewed"] },
    { no: 63, grade: "中平", titleZh: "啼血盼归", title: "The Cuckoo Calls", poemZh: "子规半夜犹啼血\n不信东风唤不回", poem: "The cuckoo cries blood at midnight still\nrefusing to believe the east wind cannot be called back", meaning: "The cuckoo crying blood at midnight: someone far away longs for you painfully, certain you will return at last. Lovers parted by a thousand hills—the thread has not snapped. When the spring east wind rises, the reunion is at hand. Pity the faithful heart on the other side: write often, fix the date of return early, and do not leave the waiting one alone against the cold night.", aspects: ["Parting, not forever", "Hold fast, return", "Spring wind returns"] },
    { no: 64, grade: "上平", titleZh: "知难而退", title: "Know When to Step Back", poemZh: "齐大非吾耦也", poem: "Qi is too great to be my mate", meaning: "Qi is too great a match: a union with too wide a gulf of family drags after-trouble in its train. If the other's house is rich and yours is humble, even success may leave you forever looking up. Know the difficulty and step back—lowering your aim is itself the lucky road. Love is not climbing; it is fitting. Find the person who fits, and the days pass easy and secure.", aspects: ["Unequal—step back", "Fit over height", "Retreat for room"] },
    { no: 65, grade: "上平", titleZh: "走出深闺", title: "Step out of the Boudoir", poemZh: "在幽闺自怜", poem: "Pitying herself in the shadowed chamber", meaning: "Shut in the inner room, sighing over yourself—when will the good match ever come? In old days propriety walled men and women apart; the times have changed, and the bond must now be walked out and won. Singles should mix and move—friendship first, marriage after—widening the circle of their days. Better to walk out than mourn at the mirror: happiness does not knock on a self-shut door.", aspects: ["Go out, mingle", "Friends first", "Reach out first"] },
    { no: 66, grade: "中", titleZh: "莫再挑剔", title: "Too Picky to Perch", poemZh: "惊起却回头\n有恨无人省\n拣尺寒枝不肯栖\n寂寞沙洲冷", poem: "Startled up, it looks back\nits grief understood by none\npicking over the cold branches, it will not perch\nand the lonely sandbar is chill", meaning: "The lone wild goose picks over the branches, refuses them all, and ends on a cold sandbar: too much pickiness leaves nowhere to roost. Standards set too high and complaints too many—soon the good chances are gone, and looking back, no helper remains to resent. Lower the demands, turn resistance into help, and accept an imperfect person. Dally longer, and there may not be a make-do branch.", aspects: ["Pickiness delays", "Lower the bar", "Turn back early"] },
    { no: 67, grade: "上", titleZh: "再试可成", title: "Try Once More", poemZh: "再，斯可矣", poem: "Twice—that is enough", meaning: "'Twice is enough': one failure does not close the account—come again, and why think three times into paralysis? A confession refused, a marriage blocked—neither is the final word. Summon the courage for one more attempt; the chance of success stands just behind. In love, over-caution loses the field—act freely, and this round will show real progress. A failure is only a place to start again.", aspects: ["Second try succeeds", "Good things grind", "Try once more"] },
    { no: 68, grade: "上平", titleZh: "情深为本", title: "Deep Love Above All", poemZh: "苟有可观\n皆有右乐\n匪必瑰奇假丽者也", poem: "Whatever has something worth seeing\nhas its own delight\nit need not be rare and strange or dazzlingly fair", meaning: "Whatever has something worth seeing has its own joy; it need not be rare, strange, or gorgeous to please. So it is with marriage: its fullness rests on the depth of love alone. Where love runs deep, no one tallies matched looks, much less counts the other's purse. Do not demand splendor in a mate—honor what is worth seeing. Where love is deep, even poverty is paradise.", aspects: ["Love over looks", "Deep love, peace", "True love keeps"] },
    { no: 69, grade: "中", titleZh: "另择佳偶", title: "Seek a Better Love", poemZh: "天下多负人\n何必是", poem: "The world is full of faithless ones\nwhy must it be this one?", meaning: "The world is wide—why weep over one false heart? They never valued you; why let them cost you body and mind as well? Lay down this mistaken love and choose a better mate: another may yet give you a lifetime of happiness. Lovesickness past all reason is the great taboo—turn back soon, and the sea is wide and the sky open. Shed no more tears for someone not worth them.", aspects: ["Leave the faithless", "Find truer love", "Turn back now"] },
    { no: 70, grade: "上平", titleZh: "利有攸往", title: "Favorable to Proceed", poemZh: "利有攸往", poem: "It is favorable to go forward", meaning: "'It is favorable to go forward': what you are asking about rewards the journey—advance, do not stand still. In love, whether someone holds your heart or marriage is on the table, this is the hour to move; the other's standing is solid and their sincerity plain, worthy of your trust. Yet even a favorable journey wants tending—win it without slacking, and the blessing will hold.", aspects: ["Go and seek", "Doable, done", "Advance and gain"] },
    { no: 71, grade: "中上", titleZh: "莫弃糟糠", title: "Forget Not the Faithful", poemZh: "虽有丝麻\n无弃菅蒯\n虽有姬姜\n无弃蕉萃", poem: "Though you have silk and hemp\ncast not aside the coarse grasses\nthough you have the noblest ladies\nabandon not your careworn wife", meaning: "Though silk and hemp are yours, do not throw away the coarse fibers; though noble beauties surround you, do not cast off the careworn one who shared the lean years. However fine the new favor, the mate of hardship may not be discarded—ingratitude is the very day fortune begins to fade. Singles: do not rank people by purse. Married: honor the old companion, and the estate endures.", aspects: ["Slight not poverty", "Keep the faithful", "Old bonds hold"] },
    { no: 72, grade: "下", titleZh: "强求无益", title: "Futility of Forcing", poemZh: "以若所为\n求若所为\n犹缘大而鱼也", poem: "With such conduct as this\nto seek such a goal as that\nis like climbing a tree to fish", meaning: "A lower stick: going after what you wish with conduct such as this is fishing up a tree—the direction is wrong, and all the labor is wasted. Unless words and conduct change, the marriage will not form; better to mend yourself than to chase in vain. Whatever is sought by the wrong road should be given up at the very step. The moment the thought turns, life returns.", aspects: ["Wrong direction", "Forcing is futile", "Change course"] },
    { no: 73, grade: "上吉", titleZh: "雨过天晴", title: "After Rain, Clear Skies", poemZh: "白云初晴\n幽鸟相逐", poem: "White clouds newly clear\nhidden birds chase one another", meaning: "The rain has passed and the sky is new; shy birds pursue each other through it—the gloom is gone, and the season of delight has come. The murk and mischance of former days is swept away: the single find their bond in daylight and pursue it freely; the paired feel love revive, birds chasing in a clear sky. This match will be made—and envied. Ride the momentum.", aspects: ["Clouds part", "Delight draws near", "Made friends again"] },
    { no: 74, grade: "中", titleZh: "相见恨晚", title: "Met Too Late", poemZh: "恨相见晚也", poem: "The sorrow of having met too late", meaning: "You met too late: the one before you is the very shape of your heart's image—but already belongs to another, and regret avails nothing. This bond has arrived a step behind; snatching love from another wounds them and you alike. Enshrine the flutter, keep to your own bounds. The loveliest things are the least durable—yield to fate and go easy: the person meant for you waits elsewhere.", aspects: ["One step late", "Met too late", "Keep to bounds"] },
    { no: 75, grade: "下", titleZh: "莫误青春", title: "Squander Not Your Youth", poemZh: "则去偷香窃玉上用心\n又不曾得甚\n自从海棠开\n想到如今", poem: "All your pains spent on stolen perfumes and jades\nand nothing ever gained\nsince the crabapple bloomed\nyou have pined until today", meaning: "A lower stick: the heart's whole cunning spent on stolen sweetness wins nothing at all. Unions founded on faces and fortunes end as strangers sharing one bed. Youth passes quickly, and time is the most pitiless of creditors—do not wager your years on a game. Singles: keep self-respect and a good name; a true bond must be bought with true feeling only. So bought, it ends well.", aspects: ["A false encounter", "Beware false hearts", "Self-respect first"] },
    { no: 76, grade: "上", titleZh: "良缘莫拒", title: "Refuse Not This Fit", poemZh: "忘足\n履之适也\n忘腰\n带之适也", poem: "Forget the foot\nthat is the shoe's fit\nforget the waist\nthat is the belt's fit", meaning: "The shoe that fits is forgotten on the foot; the belt that fits, on the waist. A bond so exactly fitted—what reason is there to refuse? The one before you matches you on every side, shoe and belt cut to your measure: hasten the union, and do not stall. In love, fit outranks finery; take this perfect ease into your keeping, and it is fortune for a lifetime.", aspects: ["Accept the fit", "Settle soon", "So fitted, joined"] },
    { no: 77, grade: "上", titleZh: "摽梅迨吉", title: "Wed in Due Season", poemZh: "标有梅\n其实七兮\n求我庶士\n迨其吉兮", poem: "The plums are falling from the bough\nseven-tenths of the fruit remains\nyou suitors who would woo me\ncome while the days are lucky", meaning: "As the plum tree sheds its fruit, the season is measured out: youth has bounds, yet the waiting heart need neither fret nor let the day slip. The suitor stands ready at the right hour—'while the days are lucky': choose a good date and settle the union. Only do not haggle over trifles in courtship; the small-minded drive people away. Generous and easy, the day arrives on its own.", aspects: ["The day nears", "Fix the date", "Choose and act"] },
    { no: 78, grade: "中", titleZh: "欲速不达", title: "Haste Makes Waste", poemZh: "欲速则不达\n见小利\n则大事不成", poem: "Hurry, and you never arrive\nsnatch at small gains\nand the great work fails", meaning: "Hurry misses the mark; snatching at small gains ruins the great enterprise. In love, those who force the pace breed their own upsets—marriage should proceed step by measured step. Greed for the little sweetness and small advantage before your eyes can cost you the lifetime matter. Keep the rhythm—neither rushing nor dragging—and the great thing forms. Steady advance is the whole of this stick.", aspects: ["Don't rush it", "Step by step", "Slow, then done"] },
    { no: 79, grade: "上", titleZh: "春景已临", title: "Spring Has Arrived", poemZh: "更洒遍客舍青青\n千缕柳色新", poem: "Again the rain sweeps the traveler's lodge fresh and green\na thousand threads of willow color new", meaning: "Spring rain has washed the dust away, and the willows stand in new color: winter is out, spring is in, and the happy event is at the door. The dull season of love is over; new chances, a new air unfold. Singles should move while the spring light lasts; the paired find the bond made new. The hour of joy has come—step forward and receive it gladly.", aspects: ["Fine spring days", "Joy draws near", "Made all new"] },
    { no: 80, grade: "上", titleZh: "乐在新知", title: "Joy in New Friends", poemZh: "悲莫悲兮生别离\n乐莫乐兮新相知", poem: "No sorrow greater than parting in life\nno joy greater than a new-found friend", meaning: "The sorrow of parting belongs to yesterday; the joy of new understanding stands before you today. The bitter taste of the old love has been fully tasted—fair weather is here, and there is nothing left to dread. New meetings and new friendship will bring courage and delight. Set down the old grief and open your arms to the new gladness: fortune rides at its height.", aspects: ["New friends coming", "Joy within reach", "Welcome the new"] },
    { no: 81, grade: "中", titleZh: "功到自成", title: "Effort Brings Success", poemZh: "经之营之\n不日成之", poem: "Plan it and build it\nand in few days it is done", meaning: "'Plan it and build it—done within days': tend the work daily, and completion comes shortly. In love, once you have judged the person worthy, draw near by honest means and cultivate the bond, and a great success will have its day. Marriage, too, is something built, not found. No shortcut exists on this stick—only diligence and sincerity. Trust it and keep on; persistence is the point.", aspects: ["Tend it daily", "Done in days", "Persist and win"] },
    { no: 82, grade: "上上", titleZh: "慎谋能断", title: "Choose Amid Many", poemZh: "行去耶\n前朱雀而后玄武\n左青龙而右白虎", poem: "Shall you go?\nVermilion Bird before, Dark Warrior behind\nAzure Dragon at the left, White Tiger at the right", meaning: "The four spirits stand guard on every side: for your gifts and beauty, admirers gather, and you cannot fix on one. Best to step back from the bustle and, somewhere quiet, plan carefully and decide firmly—weigh it through, then choose. Many suitors are not blessing; fix your eye on one and go deep—that is the true course. Among the moons held up to you, take only one.", aspects: ["Admirers abound", "Choose the one", "Decide, then win"] },
    { no: 83, grade: "下", titleZh: "断然舍之", title: "Let It Go Now", poemZh: "姑舍是", poem: "Let this one go for now", meaning: "A lower stick—one word, 'let go': set it down as the soldier cuts off a wounded hand. The bond before you should not be rejoined; clinging only breeds trouble, with no profit. Better the brave man's severed wrist than a lover's useless lingering—cut it, and seek a better match. The laying-down hurts, but it is the only live move here. Drop the old, and the new can come.", aspects: ["Give it up", "Cut the thought", "Seek anew"] },
    { no: 84, grade: "上平", titleZh: "惜取少年", title: "Cherish Your Youth", poemZh: "劝君莫惜金缕衣\n劝君惜取少年时\n花开堪折直需折\n莫待无花空折枝", poem: "I bid you not prize the gold-threaded robe\nI bid you prize the years of youth\nwhen flowers bloom and may be plucked, pluck them\ndo not wait to break a bare branch in vain", meaning: "Do not prize the gold-thread robe; prize the season of your years. When the flowers are fit to pluck, pluck: met with the right person at the right hour, take hold in time—do not wait until the bloom has passed and you break an empty branch. Youth walks this road once, and hesitation is the costliest waste. Better to pluck boldly now than repent nothing plucked.", aspects: ["Pluck in time", "Waste not youth", "Advance today"] },
    { no: 85, grade: "上上大吉", titleZh: "得其所哉", title: "Right Where You Belong", poemZh: "得其所哉\n得其所哉", poem: "It has found its rightful place\nit has found its rightful place", meaning: "'It has found its place—found its place!' cried twice over: the great sign of coming to the very station meant for you. The bond before you is your true harbor; meeting such an hour, decide without one more hesitation—stalling forfeits the chance. Singles meet the destined one; those discussing marriage win a fine match; the married find the house at rest. Fortune fills the spirit: miss it not.", aspects: ["True love arrives", "Each in place", "Decide, don't doubt"] },
    { no: 86, grade: "中", titleZh: "银河相隔", title: "Across the Milky Way", poemZh: "河汉清且浅\n相去复几许\n盈盈一水间\n脉脉不得语", poem: "The River of Stars is clear and shallow\nhow far apart, after all?\nBetween one brimming strip of water\ngazing and gazing, unable to speak", meaning: "Herdboy and Weaver stand over the Silver River: hearts close, bodies apart. Something—circumstance, study, or work—keeps the two of you from becoming a household for now; it is not any want of love but a want of season. Wait patiently and keep the thread of remembrance warm; shallow water is crossed in time. Impatience and reproach only wound what the waiting would preserve.", aspects: ["A shallow divide", "Await the crossing", "Love holds—hope"] },
    { no: 87, grade: "下", titleZh: "缘尽莫追", title: "The Phoenix Has Flown", poemZh: "便如凤去秦楼\n云敛巫山", poem: "It is as when the phoenix left the Qin tower\nand the clouds withdrew from Mount Wu", meaning: "A lower stick: the phoenix is gone from the tower, the cloud lifted off the mountain—the beloved has departed, the bond is at its end. Joining again does not suit; pressing brings no profit. Gather your heart, still your will, choose a better mate. To lose at love is not to lose at life: this door closed, another opens. Do not let one passing cloud cost you the whole mountain.", aspects: ["The bond's spent", "Don't hold on", "Choose anew"] },
    { no: 88, grade: "中", titleZh: "患难见情", title: "True Love, True Trials", poemZh: "是非吾所谓情也", poem: "This discord—is that what I call love?", meaning: "Love untried by weather snaps at the first wind; real affection must pass through dispute to show its face. Friction and quarrels within the bond are exactly the assay of its metal—no need for panic or despair. The one who can cross the squall with you is the one to trust for life; the one that shatters at a touch was never worth mourning. Test, and be tested.", aspects: ["The test's here", "Cross the storm", "Trials show truth"] },
    { no: 89, grade: "中", titleZh: "决疑在己", title: "Decide Yourself", poemZh: "卜以决疑\n不疑何卜", poem: "Divination is for settling doubt\nwhere there is no doubt, why divine?", meaning: "'Divination exists to settle doubt; where doubt is absent, why divine?' You came because the heart wavers—yet the power of decision was always your own. In love, at the crossroads, better to weigh your own case and decide boldly than to cast lots again and again. The oracle buys peace of mind; happiness is a thing you must settle for yourself. Trust others less than yourself.", aspects: ["Doubt wants deciding", "Decide it yourself", "The answer's yours"] },
    { no: 90, grade: "上", titleZh: "岂在朝暮", title: "Love Beyond Distance", poemZh: "两情若是长久时\n又岂在朝朝暮暮", poem: "If the love of two hearts holds true and long\nwhat matter the mornings and evenings apart?", meaning: "'If the love of two hearts is lasting, what matter mornings and evenings?' A lover far away, meetings few and far between: today's low spirits are passing weather, for the traveler has a day of return, and homecoming love burns warmer. Do not keep score of hours side by side—the communion of hearts is the lasting way. Wait with an easy heart, and the joy of reunion comes.", aspects: ["Parting, not sorrow", "Long love waits", "Return brings joy"] },
    { no: 91, grade: "上", titleZh: "重新出发", title: "Begin Anew", poemZh: "你往事已沉\n我只言自今", poem: "Your past has sunk away\nI speak only from today", meaning: "'The past has sunk; I speak only from today': let yesterday die with yesterday and today be born with today. However deep the old wound, do not turn it over; from this morning, act on a new resolve, and success will have its day. For those hoping to reconcile—if both are willing to turn the page and start again, an old bond can put forth new flowers.", aspects: ["Turn the page", "New from today", "Start it over"] },
    { no: 92, grade: "中", titleZh: "脚踏实地", title: "Feet on the Ground", poemZh: "明明如月\n何时可掇", poem: "Bright, bright as the moon\nwhen may it ever be plucked?", meaning: "Scooping the moon from the water: the disc shines plain to the eye, and the hand comes up empty. In love, to bank on luck or worship a glittering halo is to spend every cunning for nothing—happiness does not drop from the sky but grows from ground firm underfoot. Fold away the fantasy and work honestly at the real bond before you; there, and only there, something forms.", aspects: ["Chase no illusions", "Realism first", "Grounded, it forms"] },
    { no: 93, grade: "上上", titleZh: "及时行乐", title: "Seize the Joys", poemZh: "而浮生若梦\n为欢几何", poem: "This floating life is like a dream\nhow much joy can it hold?", meaning: "'Life floats past like a dream—how much joy does it hold?' The days are short, and gladness should be taken in season. When the heart stirs and chance offers, do not over-think it: what you judge feasible, do decisively. Every sweet hour with the one you love is a festival in itself—do not wake from the dream to repent joys unspent. Delight in the present is cherishing fate.", aspects: ["Joy in season", "Waste no hour", "Gladness—go ahead"] },
    { no: 94, grade: "中", titleZh: "谨防甜言", title: "Beware Sweet Words", poemZh: "巧言令色\n鲜矣仁", poem: "Fine words and an ingratiating face\nseldom keep company with goodness", meaning: "'Honey words and painted looks—rarely any goodness in them': the sweetest tongue does not promise a true heart. Before an eloquent pursuer—or an old flame turning at the door with sugar on its lips—keep your wits: honey can sheathe a blade. Judge conduct, not conversation. The sincere rarely speak beautifully; time shows the heart. Watch much, and believe little.", aspects: ["Beware honeyed words", "Deeds over speech", "Trust no return"] },
    { no: 95, grade: "上", titleZh: "子孙绵延", title: "A Flourishing Family", poemZh: "螽斯羽\n薨薨兮\n宜尔子孙\n绳绳兮", poem: "The katydid shakes its wings\nwith a whirring hum\nmay your children and grandchildren\ncontinue, line upon line", meaning: "The katydid whirrs its wings—children upon children, line upon unbroken line: an auspicious sign of family fortune running strong. For the married, children will be added and the household prosper; for those discussing marriage, it is likewise the omen of many sons and much blessing. An extraordinary lot, worthy of congratulations. Cherish the good fortune before you, do good deeds, and let the shade shelter those who come after.", aspects: ["Many children, blessed", "Fortune rising", "Shelter the line"] },
    { no: 96, grade: "上上", titleZh: "情钟相待", title: "Cherish the Devoted", poemZh: "虽执鞭之士\n吾亦为之", poem: "Even were he a carriage driver with the whip\nI would take my place beside him", meaning: "Where the heart is fixed, even driving a carriage would be borne gladly: in love, the heart is the thing. If the two of you are suited, let rank and trade come second—treat each other well, and that is all. The bond being joined, hold each other precious; never let it drift out of care—to lose it would be the great loss. Heart for heart, to the end.", aspects: ["Love over station", "Treat with sincerity", "Cherish, don't drop"] },
    { no: 97, grade: "中", titleZh: "修睦待人", title: "Mend Your Ways", poemZh: "归楚，楚人不信\n归汉，汉人震恐\n足下欲持是安归乎", poem: "Return to Chu, and the men of Chu distrust you\nreturn to Han, and the men of Han are afraid\nwhere then, sir, do you mean to take refuge?", meaning: "Rejected at every gate, no place to rest—such straits are sown by unkindness in one's daily dealing. If your popularity has run dry and refusals come in chains, look homeward first: have you dealt with the world generously, with people sincerely? Be good to those around you, and in your difficulty someone will stand near. Mend old quarrels, knit good ties, and the road to marriage opens again.", aspects: ["Repair the goodwill", "Look inward", "Mended, renewed"] },
    { no: 98, grade: "上", titleZh: "时来运转", title: "The Tide Turns", poemZh: "昨夜江边春草生\n艨艟巨舰一毛轻\n向来枉费推移力\n此日中流自在行", poem: "Last night by the river the spring grass grew\nthe great warship rides light as a feather\nso long one wasted strength on pushing it along\ntoday it glides free in midstream", meaning: "Spring water rises and the great ship floats light: the labor that ate your strength in vain now carries you of itself. A courtship that ground on hopeless and heavy is about to open wide—one turn of the season, and everything flows into place; the old gloom is swept off in a stroke. Rally your spirits and run with the current: fortune stands in plain view.", aspects: ["Flows into place", "Free and easy", "Ride the stream"] },
    { no: 99, grade: "中", titleZh: "先苦后甘", title: "Bitter First, Sweet After", poemZh: "必先苦其心志", poem: "First the heart's will must be tempered in suffering", meaning: "'First the heart's will is mortified': before the marriage is won, tempering is owed. The labor of pursuit, the ache of adjustment—all of it composts the good fruit of love; the one who quits loses everything already spent. Those asking of marriage meet hard first, easy after; those asking of an old bond must bow and taste the bitter first. Outlast the bitter, and the sweet is yours.", aspects: ["Bitter then sweet", "Tempering makes it", "Endure the bitter"] },
    { no: 100, grade: "上上", titleZh: "花好月圆", title: "Flowers, Moon, Longevity", poemZh: "花好\n月圆\n人寿", poem: "Flowers at their finest\nthe moon at full\nand length of days", meaning: "The last of the hundred: flowers at their finest, the moon at full, long life—every wish of the human heart gathered into one. In marriage it is the union of two perfections, a hundred years of reunion: singles see the bond come round and full; the married grow old together. Draw this stick and rejoice without reserve. Keep gratitude, knit good ties, and let the fullness go round.", aspects: ["Complete content", "Grow old together", "Perfection itself"] },
  ],
};
